const config=window.AFRIRISE_CONFIG;
const publicCampaigns=[];let paymentConfig={paymentsEnabled:false,monthlyEnabled:false};let selectedCampaign=null;let attemptKey=null;let lastPayload=null;
const detailsLabels={activities:'What your donation supports',beneficiaries:'Who benefits',location:'Location',eligibility:'Eligibility',selection_process:'How participants are selected',budget:'Itemised budget (USD)',timeline:'Delivery timeline',underfunding:'If the target is not reached',excess_funds:'If the target is exceeded',delivery_impossible:'If delivery becomes impossible',update_schedule:'When updates will arrive',refunds:'Refunds and reallocations',cancellation:'Recurring cancellation',privacy:'Privacy',safeguarding:'Safeguarding',complaints:'Complaints',support_email:'Payment support contact'};
function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function api(path,options={}){if(!config.apiBase)throw new Error('The donation service has not been connected yet.');const response=await fetch(config.apiBase+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const value=await response.json();if(!response.ok)throw new Error(value.error||'The request could not be completed.');return value}
async function loadCampaigns(){
 if(!config.apiBase)return;
 try{const [campaigns,status]=await Promise.all([api('/campaigns'),api('/config')]);paymentConfig=status;publicCampaigns.push(...campaigns);const select=document.querySelector('#designation');if(campaigns.length){select.innerHTML=campaigns.map(c=>`<option value="${escapeHTML(c.id)}">${escapeHTML(c.title)}</option>`).join('');selectedCampaign=campaigns[0];}syncDonationState();}catch{document.querySelector('#gift-feedback').textContent='The donation service is temporarily unavailable.'}
}
function syncDonationState(){
 const ready=paymentConfig.paymentsEnabled&&selectedCampaign?.accepting_donations;
 document.querySelector('#checkout-notice').innerHTML=ready?'<strong>Secure payment with Bachs.</strong><p>Your selected donation is charged in USD. Card details are entered on Bachs’s hosted checkout.</p>':'<strong>Checkout is not open yet.</strong><p>You can explore the donation journey. No payment is collected until campaign details and the payment service are connected.</p>';
 const monthly=frequency==='Monthly';document.querySelector('#recurring-consent').hidden=!monthly;document.querySelector('#donor-recurring').required=monthly;
 document.querySelector('#checkout-button').disabled=!ready||(monthly&&!paymentConfig.monthlyEnabled);
 document.querySelector('#checkout-button').textContent=ready?'Continue to Bachs ↗':'Payment setup pending';
 document.querySelector('#donation-review').textContent=`${document.querySelector('#selection-summary').textContent} · ${selectedCampaign?.title||document.querySelector('#designation').selectedOptions[0].textContent}`;
}
document.querySelector('#designation').addEventListener('change',e=>{selectedCampaign=publicCampaigns.find(c=>c.id===e.target.value);syncDonationState()});
document.querySelectorAll('[data-frequency],[data-amount]').forEach(b=>b.addEventListener('click',syncDonationState));document.querySelector('#custom-amount').addEventListener('input',syncDonationState);
document.querySelector('#review-gift').addEventListener('click',()=>{const feedback=document.querySelector('#gift-feedback');if(!Number.isFinite(amount)||amount<1||amount>1000000||Math.abs(amount*100-Math.round(amount*100))>0.000001){feedback.textContent='Choose $1–$1,000,000 USD, with at most two decimal places.';return}document.querySelector('#donor-form').hidden=false;syncDonationState();feedback.textContent='Review your details and campaign information before continuing.';document.querySelector('#donor-form').scrollIntoView({block:'nearest'})});
document.querySelector('#campaign-details-button').addEventListener('click',()=>{const c=selectedCampaign;showContent('CAMPAIGN INFORMATION',c?.title||'The $500,000 founding appeal',`<p>Fundraising goal: <strong>$500,000 USD</strong>. ${c?'Review the published programme information below.':'Programme delivery and funding rules are awaiting approval. No contributions are being accepted.'}</p><div class="campaign-disclosures">${Object.entries(detailsLabels).map(([k,label])=>`<section><h3>${label}</h3><p>${escapeHTML(c?.[k]||'Awaiting approval and publication.')}</p></section>`).join('')}</div>`,false)});
document.querySelector('#donor-form').addEventListener('submit',async e=>{
 e.preventDefault();const feedback=document.querySelector('#gift-feedback'),button=document.querySelector('#checkout-button');if(!paymentConfig.paymentsEnabled||!selectedCampaign)return;
 const payload={currency:'USD',amount:amount.toFixed(2),frequency:frequency==='Monthly'?'monthly':'once',campaignId:selectedCampaign.id,termsVersion:selectedCampaign.terms_version,email:document.querySelector('#donor-email').value.trim(),name:document.querySelector('#donor-name').value.trim(),anonymous:document.querySelector('#donor-anonymous').checked,newsletter:document.querySelector('#donor-newsletter').checked,termsAccepted:document.querySelector('#donor-terms').checked,privacyAccepted:document.querySelector('#donor-privacy').checked,recurringAccepted:document.querySelector('#donor-recurring').checked};
 const fingerprint=JSON.stringify(payload);if(lastPayload!==fingerprint){attemptKey=crypto.randomUUID();lastPayload=fingerprint}button.disabled=true;feedback.textContent='Preparing secure checkout…';
 try{const result=await api('/checkout',{method:'POST',headers:{'Idempotency-Key':attemptKey},body:fingerprint});sessionStorage.setItem('afririse-status-token',result.statusToken);const target=new URL(result.checkoutUrl);if(target.protocol!=='https:'||target.hostname!=='checkout.bachs.io')throw new Error('Invalid payment redirect.');location.assign(target.href)}catch(error){feedback.textContent=error.message;button.disabled=false}
});
loadCampaigns();
